patch_result.patch:
--- a/ext/spl/spl_fixedarray.c
+++ b/ext/spl/spl_fixedarray.c
@@ -211,7 +211,16 @@
 	HashTable *ht = zend_std_get_properties(obj);

 	*table = intern->array.elements;
-	*n = (int)intern->array.size;
+	if (UNEXPECTED(intern->array.size > INT_MAX)) {
+		/*
+		 * get_gc() reports the element count via int*. Prevent truncation of very
+		 * large SplFixedArray sizes, which could become negative and later be
+		 * interpreted as a huge unsigned count by GC.
+		 */
+		*n = 0;
+	} else {
+		*n = (int) intern->array.size;
+	}

 	return ht;
 }

args:
@@ -211,7 +211,14 @@ static HashTable* spl_fixedarray_object_get_gc(zend_object *obj, zval **table,
 	HashTable *ht = zend_std_get_properties(obj);

 	*table = intern->array.elements;
-	*n = (int)intern->array.size;
+	if (UNEXPECTED(intern->array.size > INT_MAX)) {
+		/*
+		 * get_gc() reports the element count via int*. Prevent truncation of very
+		 * large SplFixedArray sizes, which could become negative and later be
+		 * interpreted as a huge unsigned count by GC.
+		 */
+		*n = 0;
+	} else {
+		*n = (int) intern->array.size;
+	}

 	return ht;
 }
